on conflict (provider_key, service_key, country_code, category, direction, unit) do update set provider_rate=excluded.provider_rate,pricing_mode=excluded.pricing_mode,additive_fees=excluded.additive_fees,source_url=excluded.source_url,source_note=excluded.source_note,last_verified_at=excluded.last_verified_at,active=true,updated_at=now();